local PotionBrewer = {}
local PRODUCTS = {
    healing_potion = { name = "Zdravilni napoj", herbCost = 2, waterCost = 1, time = 2, cost = 30, healingPower = 40, happiness = 1, description = "Zdravilni napoj za lažje poškodbe." },
    stamina_potion = { name = "Napoj vzdržljivosti", herbCost = 2, honeyCost = 1, waterCost = 1, time = 3, cost = 65, healingPower = 55, prestige = 2, description = "Napoj za obnovo moči." },
    antidote_potion = { name = "Protistrup", herbCost = 3, honeyCost = 1, silverCost = 1, waterCost = 1, time = 5, cost = 150, healingPower = 70, prestige = 5, happiness = 1, description = "Protistrup za zastrupitve." },
    silver_vial_potion = { name = "Srebrnoflašni napoj", herbCost = 3, honeyCost = 1, silverCost = 1, goldCost = 1, waterCost = 1, time = 8, cost = 350, healingPower = 82, prestige = 10, happiness = 2, description = "Napoj v srebrnem vialu za plemiče." },
    gold_vial_elixir = { name = "Zlatoflašni eliksir", herbCost = 4, honeyCost = 2, goldCost = 1, jewelCost = 1, silverCost = 1, waterCost = 1, time = 11, cost = 750, healingPower = 92, prestige = 18, happiness = 4, description = "Eliksir v zlatem vialu za visoke plemiče." },
    royal_grand_potion = { name = "Kraljevski veliki napoj", herbCost = 6, honeyCost = 3, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, waterCost = 2, time = 16, cost = 2000, healingPower = 100, prestige = 42, happiness = 9, description = "Veliki kraljevski napoj z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Napojarska delavnica", cost = { gold = 280, wood = 130, stone = 250 }, upkeep = 7, qualityBonus = 5 },
    brewing_room = { name = "Varilnica", cost = { gold = 900, wood = 250, stone = 400, herb = 10 }, upkeep = 22, qualityBonus = 18 },
    alchemy_lab = { name = "Alkemijski laboratorij", cost = { gold = 2300, wood = 350, stone = 700, silver = 30, glass = 8 }, upkeep = 58, qualityBonus = 30 },
    royal_potion_atelier = { name = "Kraljevski atelje napojev", cost = { gold = 9200, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 185, qualityBonus = 55, prestigeBonus = 40 },
}
PotionBrewer.herbStock = 22; PotionBrewer.honeyStock = 14; PotionBrewer.waterStock = 18; PotionBrewer.silverStock = 8; PotionBrewer.goldStock = 6; PotionBrewer.jewelStock = 6; PotionBrewer.pearlStock = 4
PotionBrewer.productStock = {}; PotionBrewer.buildings = {}; PotionBrewer.maker = nil; PotionBrewer.activeMaking = {}; PotionBrewer.totalProducts = 0; PotionBrewer.dayTimer = 0
function PotionBrewer.init() PotionBrewer.herbStock=22; PotionBrewer.honeyStock=14; PotionBrewer.waterStock=18; PotionBrewer.silverStock=8; PotionBrewer.goldStock=6; PotionBrewer.jewelStock=6; PotionBrewer.pearlStock=4; PotionBrewer.productStock={}; PotionBrewer.buildings={}; PotionBrewer.maker=nil; PotionBrewer.activeMaking={}; PotionBrewer.totalProducts=0; PotionBrewer.dayTimer=0; print("[PotionBrewer] Royal Potion Brewer System initialized (6 products, 4 buildings)") end
function PotionBrewer.hireMaker(n,s) s=s or math.random(50,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PotionBrewer.maker={name=n or ("Napojar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Napojar najet: %s (spretnost: %d)",PotionBrewer.maker.name,s),"success") end; return true end
function PotionBrewer.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PotionBrewer.build(id) local ok,e=PotionBrewer.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PotionBrewer.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PotionBrewer.getQualityBonus() local b=0; for _,bd in ipairs(PotionBrewer.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PotionBrewer.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.herbCost and PotionBrewer.herbStock<(d.herbCost or 0) then return false,"Premalo zelišč" end; if d.honeyCost and PotionBrewer.honeyStock<(d.honeyCost or 0) then return false,"Premalo medu" end; if d.waterCost and PotionBrewer.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.silverCost and PotionBrewer.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PotionBrewer.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PotionBrewer.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PotionBrewer.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PotionBrewer.buildings==0 then return false,"Potrebna delavnica" end; if not PotionBrewer.maker then return false,"Potreben napojar" end; return true end
function PotionBrewer.make(pt,qty) qty=qty or 1; local ok,e=PotionBrewer.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.herbCost then PotionBrewer.herbStock=PotionBrewer.herbStock-d.herbCost*qty end; if d.honeyCost then PotionBrewer.honeyStock=PotionBrewer.honeyStock-d.honeyCost*qty end; if d.waterCost then PotionBrewer.waterStock=PotionBrewer.waterStock-d.waterCost*qty end; if d.silverCost then PotionBrewer.silverStock=PotionBrewer.silverStock-d.silverCost*qty end; if d.goldCost then PotionBrewer.goldStock=PotionBrewer.goldStock-d.goldCost*qty end; if d.jewelCost then PotionBrewer.jewelStock=PotionBrewer.jewelStock-d.jewelCost*qty end; if d.pearlCost then PotionBrewer.pearlStock=PotionBrewer.pearlStock-d.pearlCost*qty end; local t=d.time; if PotionBrewer.maker then t=math.max(1,t-math.floor(PotionBrewer.maker.skill/12)) end; table.insert(PotionBrewer.activeMaking,{id="potion_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,healingPower=d.healingPower or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PotionBrewer.completeMaking(m) local q=1.0+(PotionBrewer.getQualityBonus()/100); if PotionBrewer.maker then q=q+(PotionBrewer.maker.skill/180) end; q=math.min(2.0,q); PotionBrewer.productStock[m.productType]=(PotionBrewer.productStock[m.productType] or 0)+m.quantity; PotionBrewer.totalProducts=PotionBrewer.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PotionBrewer.maker then PotionBrewer.maker.itemsMade=PotionBrewer.maker.itemsMade+m.quantity; if math.random()<0.20 then PotionBrewer.maker.skill=math.min(100,PotionBrewer.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Napoj skuhan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"potion.completed",{productName=m.productName,healingPower=m.healingPower,prestige=m.prestige,happiness=m.happiness}) end end
function PotionBrewer.update(dt) if not _G.state then return end; PotionBrewer.dayTimer=PotionBrewer.dayTimer+dt; if PotionBrewer.dayTimer>=30 then PotionBrewer.dayTimer=0; for i=#PotionBrewer.activeMaking,1,-1 do local m=PotionBrewer.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PotionBrewer.completeMaking(m); table.remove(PotionBrewer.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PotionBrewer.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PotionBrewer.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PotionBrewer.getStats() return {herbStock=PotionBrewer.herbStock,honeyStock=PotionBrewer.honeyStock,waterStock=PotionBrewer.waterStock,silverStock=PotionBrewer.silverStock,goldStock=PotionBrewer.goldStock,jewelStock=PotionBrewer.jewelStock,pearlStock=PotionBrewer.pearlStock,productStock=PotionBrewer.productStock,numBuildings=#PotionBrewer.buildings,hasMaker=PotionBrewer.maker~=nil,makerName=PotionBrewer.maker and PotionBrewer.maker.name or "—",makerSkill=PotionBrewer.maker and PotionBrewer.maker.skill or 0,activeMaking=#PotionBrewer.activeMaking,totalProducts=PotionBrewer.totalProducts} end
return PotionBrewer
